test('unsubmitted drafts stay scoped and source revocation removes submitted drafts from other companies',async()=>{await begin();await accept();await joinAna();const {e,run}=await confirmedMissing();await post(draftCreateBody(run));const d=state().evidenceDrafts[0],a=areaRecord();await post({action:'inboxArea',...inboxScope,record:a,noSensitiveData:true});await post({action:'draftEdit',...inboxScope,draftId:d.id,fields:{...d.fields,areaId:a.id},sourceChecked:true});m.setUser(home);await post({action:'share',evidenceId:e,companyIds:['contents'],includeADPA:false,consent:true});m.setUser(ana);assert.deepEqual((await (await get(jobId)).json()).inbox.evidenceDrafts,[]);m.setUser(arman);await post({action:'draftSubmit',...inboxScope,draftId:d.id,note:'For review',sourceChecked:true});m.setUser(ana);assert.equal((await (await get(jobId)).json()).inbox.evidenceDrafts.length,1);assert.equal((await post({action:'draftReview',companyId:'contents',companyVersion:1,draftId:d.id,decision:'Reviewed for handoff',note:'Not requester',sourceChecked:true})).status,400);m.setUser(home);await post({action:'share',evidenceId:e,companyIds:[],includeADPA:false,consent:true});m.setUser(ana);assert.deepEqual((await (await get(jobId)).json()).inbox.evidenceDrafts,[]);});
