test('physical contents reference prevents duplicate drafts across separate confirmed photos',async()=>{await begin();await accept();const {e,run}=await confirmedMissing(),a=areaRecord(),subject={id:crypto.randomUUID(),kind:'Contents item',label:'Refrigerator',originalAreaId:a.id,inventoryRef:'FRIDGE-1'};await post({action:'inboxArea',...inboxScope,record:a,noSensitiveData:true});await post({action:'inboxSubject',...inboxScope,record:subject,noSensitiveData:true});await post(draftCreateBody(run));const d=state().evidenceDrafts[0];await post({action:'draftEdit',...inboxScope,draftId:d.id,fields:{...d.fields,areaId:a.id,subjectId:subject.id},sourceChecked:true});const result=photoResult();result.findings[0].subjectId=subject.id;result.findings[0].areaId=a.id;await photoPost({action:'manual',...inboxScope,evidenceId:e,result,sourceChecked:true});assert.equal((await post(draftCreateBody(state().photoRuns.at(-1)))).status,400);await post({action:'draftDismiss',...inboxScope,draftId:d.id,note:'Replacing with the better confirmed reference'});assert.equal((await post(draftCreateBody(state().photoRuns.at(-1)))).status,200);});
test('ADPA handoff review requires submitted draft and all originals explicitly shared under current engagement',async()=>{const {e,d}=await createContentsDraft(),a=areaRecord();await post({action:'inboxArea',...inboxScope,record:a,noSensitiveData:true});await post({action:'draftEdit',...inboxScope,draftId:d.id,fields:{...d.fields,areaId:a.id},sourceChecked:true});await post({action:'draftSubmit',...inboxScope,draftId:d.id,note:'Please review the sourced lead',sourceChecked:true});await connect();m.setUser(owner);assert.equal((await post({action:'draftReview',draftId:d.id,decision:'Reviewed for handoff',note:'No source grant',sourceChecked:true})).status,400);m.setUser(home);await post({action:'share',evidenceId:e,companyIds:[],includeADPA:true,consent:true});m.setUser(owner);assert.equal((await post({action:'draftReview',draftId:d.id,decision:'Reviewed for handoff',note:'Checked original; quantities still unknown',sourceChecked:true})).status,200);m.sqlite.prepare("DELETE FROM evidence WHERE id='engagement'").run();assert.deepEqual((await (await get(jobId)).json()).inbox.evidenceDrafts,[]);});
const transferApi=await import(new URL('draft-transfer-route.mjs',base)),transferLib=await import(new URL('draft-transfer.mjs',base));
const transferGet=(claimId='claim')=>transferApi.GET(new Request('https://claims.test/api/draft-transfer?claimId='+claimId));
const transferPost=body=>transferApi.POST(new Request('https://claims.test/api/draft-transfer?'+(body.action==='send'?'jobId='+jobId:'claimId=claim'),{method:'POST',headers:{origin:'https://claims.test','Content-Type':'application/json'},body:JSON.stringify({jobVersion:row().version,claimVersion:m.sqlite.prepare("SELECT version FROM claims WHERE id='claim'").get()?.version,...(body.action==='send'?{draftRevision:state().evidenceDrafts?.find(d=>d.id===body.draftId)?.history.length}:{}),...body})}));
async function readyTransfer(kind='Contents item',qty='1'){await begin();await accept();const e=await photoEvidence(),r=photoResult();r.findings[0].kind=kind==='Scope item'?'Building damage':'Contents';await photoPost({action:'manual',...inboxScope,evidenceId:e,result:r,sourceChecked:true});const run=state().photoRuns[0];await post(draftCreateBody(run,{kind}));const d=state().evidenceDrafts[0],a=areaRecord();await post({action:'inboxArea',...inboxScope,record:a,noSensitiveData:true});const fields={...d.fields,areaId:a.id,quantity:qty,...(qty?{unit:'EA',quantityBasis:'One physical item counted in center of original photo',basisEvidenceId:e,basisLocator:'Center of photo'}:{})};await post({action:'draftEdit',...inboxScope,draftId:d.id,fields,sourceChecked:true});await post({action:'draftSubmit',...inboxScope,draftId:d.id,note:'Source checked',sourceChecked:true});await post({action:'draftReview',...inboxScope,draftId:d.id,decision:'Reviewed for handoff',note:'Count and source checked',sourceChecked:true});await connect();m.setUser(home);await post({action:'share',evidenceId:e,companyIds:[],includeADPA:true,consent:true});m.setUser(arman);return {e,d:state().evidenceDrafts[0]};}
const acceptance=t=>({action:'accept',transferId:t.id,roomId:'',roomName:'Kitchen',tag:'FRIDGE-1',operation:'Documented repair work',workKey:'KITCHEN-WALL-1',unit:'EA',locator:'Center of image',note:'Checked sources, identity, count and destination; price still unknown',sourceChecked:true,duplicateChecked:true});
test('reviewed contents draft enters correct claim intake and ADPA accepts a sourced working inventory item',async()=>{const {e,d}=await readyTransfer();let r=await transferPost({action:'send',...inboxScope,draftId:d.id,destination:'Contents inventory',confirmed:true});assert.equal(r.status,200,await r.clone().text());let cs=JSON.parse(m.sqlite.prepare("SELECT state FROM claims WHERE id='claim'").get().state);assert.equal(cs.contentsCare,undefined);const t=cs.evidenceTransfers[0];m.setUser(owner);r=await transferPost(acceptance(t));assert.equal(r.status,200,await r.clone().text());cs=JSON.parse(m.sqlite.prepare("SELECT state FROM claims WHERE id='claim'").get().state);assert.equal(cs.contentsCare.items[0].quantity,'1');assert.equal(cs.contentsCare.items[0].tag,'FRIDGE-1');assert.equal(cs.contentsCare.items[0].disposition,'Needs review');assert.equal(cs.contentsCare.items[0].brand,undefined);assert.equal(cs.evidenceTransfers[0].status,'Accepted');const original=m.sqlite.prepare('SELECT * FROM evidence WHERE id=?').get(cs.contentsCare.items[0].documentId);assert.ok(m.storage.has(original.object_key));assert.equal(JSON.parse(original.sources)[0].sharedEvidenceId,e);assert.equal(state().draftTransfers[0].status,'Accepted into working module');assert.equal((await transferPost(acceptance(t))).status,409);});
test('scope acceptance creates unpriced reconstruction draft with explicit room, operation and work group',async()=>{const {d}=await readyTransfer('Scope item');const sent=await transferPost({action:'send',...inboxScope,draftId:d.id,destination:'Reconstruction scope',confirmed:true});assert.equal(sent.status,200);const t=JSON.parse(m.sqlite.prepare("SELECT state FROM claims WHERE id='claim'").get().state).evidenceTransfers[0];m.setUser(owner);let r=await transferPost({...acceptance(t),unit:'SF'});assert.equal(r.status,400);r=await transferPost(acceptance(t));assert.equal(r.status,200,await r.clone().text());const cs=JSON.parse(m.sqlite.prepare("SELECT state FROM claims WHERE id='claim'").get().state);assert.equal(cs.water.lines[0].phase,'Reconstruction');assert.equal(cs.water.lines[0].unitPrice,'');assert.equal(cs.water.lines[0].status,'Draft');assert.equal(cs.water.rooms[0].length,'');assert.ok(cs.draftTransferSources[cs.water.lines[0].id]);});
test('unknown quantities can be sent for review but acceptance is blocked and return reopens source draft',async()=>{const {d}=await readyTransfer('Contents item','');assert.equal((await transferPost({action:'send',...inboxScope,draftId:d.id,destination:'Contents inventory',confirmed:true})).status,200);const t=JSON.parse(m.sqlite.prepare("SELECT state FROM claims WHERE id='claim'").get().state).evidenceTransfers[0];m.setUser(owner);assert.equal((await transferPost(acceptance(t))).status,400);assert.equal((await transferPost({action:'return',transferId:t.id,note:'Document whole count with original basis'})).status,200);assert.equal(state().evidenceDrafts[0].status,'Draft');assert.equal(state().draftTransfers[0].status,'Returned for correction');assert.equal(JSON.parse(m.sqlite.prepare("SELECT state FROM claims WHERE id='claim'").get().state).contentsCare,undefined);});
