test('duplicate physical tags are blocked before a second inventory count is accepted',async()=>{const {d}=await readyTransfer();await transferPost({action:'send',...inboxScope,draftId:d.id,destination:'Contents inventory',confirmed:true});const t=JSON.parse(m.sqlite.prepare("SELECT state FROM claims WHERE id='claim'").get().state).evidenceTransfers[0];m.sqlite.prepare("UPDATE claims SET state=json_set(state,'$.contentsCare',json(?)) WHERE id='claim'").run(JSON.stringify({items:[{id:'existing',tag:'FRIDGE-1',description:'Existing refrigerator',quantity:'1'}]}));m.setUser(owner);assert.equal((await transferPost(acceptance(t))).status,400);assert.equal(JSON.parse(m.sqlite.prepare("SELECT state FROM claims WHERE id='claim'").get().state).contentsCare.items.length,1);});
test('revoked consent pauses destination intake and prevents acceptance and evidence retention',async()=>{const {d,e}=await readyTransfer();await transferPost({action:'send',...inboxScope,draftId:d.id,destination:'Contents inventory',confirmed:true});const t=JSON.parse(m.sqlite.prepare("SELECT state FROM claims WHERE id='claim'").get().state).evidenceTransfers[0];m.setUser(home);await post({action:'share',evidenceId:e,companyIds:[],includeADPA:false,consent:true});m.setUser(owner);assert.match((await (await transferGet()).json()).rows[0].status,/Paused/);assert.equal((await transferPost(acceptance(t))).status,409);assert.equal(m.sqlite.prepare("SELECT COUNT(*) n FROM evidence WHERE category='Shared job evidence'").get().n,0);m.setUser(arman);assert.equal((await transferGet()).status,403);});
test('changed source bytes are rejected before acceptance and leave intake pending',async()=>{const {d}=await readyTransfer();await transferPost({action:'send',...inboxScope,draftId:d.id,destination:'Contents inventory',confirmed:true});const t=JSON.parse(m.sqlite.prepare("SELECT state FROM claims WHERE id='claim'").get().state).evidenceTransfers[0];m.storage.set('original/damage',{async arrayBuffer(){return new Uint8Array([1,2,3]).buffer;}});m.setUser(owner);assert.equal((await transferPost(acceptance(t))).status,409);assert.equal(JSON.parse(m.sqlite.prepare("SELECT state FROM claims WHERE id='claim'").get().state).evidenceTransfers[0].status,'Pending');});
test('concurrent source job change during retained upload leaves both destination count and receipt unaccepted',async()=>{const {d}=await readyTransfer();await transferPost({action:'send',...inboxScope,draftId:d.id,destination:'Contents inventory',confirmed:true});const t=JSON.parse(m.sqlite.prepare("SELECT state FROM claims WHERE id='claim'").get().state).evidenceTransfers[0],set=m.storage.set.bind(m.storage);let changed=false;m.storage.set=(key,value)=>{if(!changed&&String(key).includes('/shared/')){changed=true;m.sqlite.prepare('UPDATE shared_jobs SET version=version+1 WHERE id=?').run(jobId);}return set(key,value);};m.setUser(owner);try{assert.equal((await transferPost(acceptance(t))).status,409);const cs=JSON.parse(m.sqlite.prepare("SELECT state FROM claims WHERE id='claim'").get().state);assert.equal(cs.contentsCare,undefined);assert.equal(cs.evidenceTransfers[0].status,'Pending');assert.equal(state().draftTransfers[0].status,'Pending ADPA acceptance');assert.equal(m.sqlite.prepare("SELECT COUNT(*) n FROM evidence WHERE category='Shared job evidence'").get().n,0);}finally{m.storage.set=set;}});
