test('authorized shared organization helps a contents company find originals without inheriting mitigation review',async()=>{await begin();await accept();await joinAna();m.setUser(arman);const a=areaRecord();await post({action:'inboxArea',...inboxScope,record:a,noSensitiveData:true});const s={id:crypto.randomUUID(),kind:'Contents item',label:'Kitchen refrigerator',originalAreaId:a.id,inventoryRef:'FRIDGE-1'};await post({action:'inboxSubject',...inboxScope,record:s,noSensitiveData:true});const e=await contribute();assert.equal((await post(review(e,{areaIds:[a.id],subjectIds:[s.id],classification:'Contents',status:'Reviewed',reviewScope:'Whole file',locator:'Page 1',note:'Reviewed source item'}))).status,200);m.setUser(home);await post({action:'share',evidenceId:e,companyIds:['contents'],includeADPA:false,consent:true});m.setUser(ana);let v=await(await get(jobId)).json(),f=v.inbox.files[0],context=organization.inboxOrganization(f,'contents',v.inbox);assert.equal(context.classification,'Contents');assert.equal(context.borrowed,true);assert.ok(context.searchText.includes('fridge-1'));assert.ok(context.searchText.includes('kitchen'));assert.ok(context.areaIds.includes(a.id));assert.equal(f.tags.some(t=>t.role==='contents'),false);m.setUser(home);await post({action:'share',evidenceId:e,companyIds:[],includeADPA:false,consent:true});m.setUser(ana);v=await(await get(jobId)).json();assert.deepEqual(v.inbox.files,[]);assert.deepEqual(v.inbox.subjects,[]);});
test('one workspace cannot create another reference for the same contents tag after relocation',async()=>{await begin();await accept();m.setUser(arman);const a=areaRecord(),b={...areaRecord(),name:'Storage'};await post({action:'inboxArea',...inboxScope,record:a,noSensitiveData:true});await post({action:'inboxArea',...inboxScope,record:b,noSensitiveData:true});const s={id:crypto.randomUUID(),kind:'Contents item',label:'Refrigerator',originalAreaId:a.id,inventoryRef:'FRIDGE-1'};assert.equal((await post({action:'inboxSubject',...inboxScope,record:s,noSensitiveData:true})).status,200);assert.equal((await post({action:'inboxSubject',...inboxScope,record:{...s,id:crypto.randomUUID(),label:'Moved refrigerator',originalAreaId:b.id,inventoryRef:' fridge-1 '},noSensitiveData:true})).status,400);assert.equal(state().inboxSubjects.length,1);});
test('stale tags do not route a changed original and own explicit classification takes precedence over borrowed organization',()=>{const view={areas:[{id:'room',name:'Kitchen'}],subjects:[{id:'item',label:'Fridge',inventoryRef:'FRIDGE-1',originalAreaId:'room'}]},file={title:'Photo',filename:'photo.jpg',available:true,tags:[{role:'water',stale:false,areaIds:['room'],subjectIds:['item'],classification:'Contents'}]};assert.equal(organization.inboxOrganization(file,'contents',view).classification,'Contents');const stale={...file,tags:[{...file.tags[0],stale:true}]};assert.equal(organization.inboxOrganization(stale,'contents',view).classification,'Unassigned');assert.deepEqual(organization.inboxOrganization({...file,available:false},'contents',view).areaIds,[]);const own={...file,tags:[...file.tags,{role:'contents',stale:false,areaIds:[],subjectIds:[],classification:'Unassigned'}]};assert.equal(organization.inboxOrganization(own,'contents',view).borrowed,false);assert.equal(organization.inboxOrganization(own,'contents',view).classification,'Unassigned');});
test('shared inbox MIME fallback supports supported phone originals and CSV without relabeling unsupported HEIC',()=>{assert.equal(organization.inboxUploadMime('photo.JPG',''),'image/jpeg');assert.equal(organization.inboxUploadMime('audio.m4a','application/octet-stream'),'audio/mp4');assert.equal(organization.inboxUploadMime('inventory.csv','application/vnd.ms-excel'),'text/csv');assert.equal(organization.inboxUploadMime('photo.heic','image/heic'),'image/heic');assert.equal(organization.inboxUploadMime('unknown.file',''),'application/octet-stream');});
test('authorized CSV originals are stored privately without automatically sharing or reviewing them',async()=>{await begin();await accept();m.setUser(home);const r=await inboxUploadApi.POST(new Request('https://claims.test/api/evidence-inbox-upload?jobId='+jobId,{method:'POST',headers:{origin:'https://claims.test','Content-Type':'text/csv','X-Filename':'inventory.csv','X-Job-Version':String(row().version),'X-Evidence-Reviewed':'true','X-Inbox-Context':encodeURIComponent(JSON.stringify({title:'Inventory original',description:'Synthetic inventory file',areaIds:[],subjectIds:[],classification:'Contents'}))},body:'Item,Count\nChair,1'}));assert.equal(r.status,201,await r.clone().text());const e=(await r.json()).evidenceId;assert.equal(state().evidence.at(-1).includeADPA,false);assert.deepEqual(state().evidence.at(-1).companyIds,[]);m.setUser(arman);assert.equal((await file(e)).status,404);});


test('photo findings require the source version opened by the reviewer even after a valid job refresh',async()=>{await begin();await accept();const id=await photoEvidence(),before=state().evidence.find(e=>e.id===id),proof={digest:before.digest,sourceCreated:before.sourceCreated,revision:before.revision};
 let j=state();j.evidence=j.evidence.map(e=>e.id===id?{...e,revision:'2'}:e);m.sqlite.prepare('UPDATE shared_jobs SET state=?,version=version+1 WHERE id=?').run(JSON.stringify(j),jobId);m.sqlite.prepare("UPDATE company_assets SET revision='2' WHERE id='damage'").run();
 const current=(await(await get(jobId)).json()).inbox.files.find(f=>f.evidenceId===id);assert.equal(current.available,true);assert.equal(current.sourceProof.revision,'2');assert.equal(photoLib.samePhotoSource(proof,current.sourceProof),false);
 const r=await photoPost({action:'manual',...inboxScope,evidenceId:id,sourceProof:proof,result:photoResult(),sourceChecked:true});assert.equal(r.status,409);assert.match((await r.json()).error,/version differs/);assert.equal(state().photoRuns,undefined);
 assert.equal((await photoPost({action:'manual',...inboxScope,evidenceId:id,sourceProof:current.sourceProof,result:photoResult(),sourceChecked:true})).status,200);
});
test('photo requests without source proof or with a mismatched digest cannot save or call AI',async()=>{await begin();await accept();const id=await photoEvidence();let r=await photoPost({action:'manual',...inboxScope,evidenceId:id,sourceProof:undefined,result:photoResult(),sourceChecked:true});assert.equal(r.status,400);const e=state().evidence.find(e=>e.id===id);r=await photoPost({action:'examine',...inboxScope,evidenceId:id,sourceProof:{digest:'0'.repeat(64),sourceCreated:e.sourceCreated,revision:e.revision},consent:true});assert.equal(r.status,409);assert.equal(state().photoRuns,undefined);});
test('photo finding type must match a selected authorized physical reference',async()=>{await begin();await accept();const id=await photoEvidence(),a=areaRecord(),s={id:crypto.randomUUID(),kind:'Building component',label:'Kitchen wall',originalAreaId:a.id,inventoryRef:''};await post({action:'inboxArea',...inboxScope,record:a,noSensitiveData:true});await post({action:'inboxSubject',...inboxScope,record:s,noSensitiveData:true});let result=photoResult();result.findings[0].subjectId=s.id;assert.equal((await photoPost({action:'manual',...inboxScope,evidenceId:id,result,sourceChecked:true})).status,400);assert.equal(state().photoRuns,undefined);result.findings[0].kind='Building damage';assert.equal((await photoPost({action:'manual',...inboxScope,evidenceId:id,result,sourceChecked:true})).status,200);assert.throws(()=>photoLib.validatePhotoResult({...photoResult(),findings:[{...photoResult().findings[0],kind:'Building damage',subjectId:'contents'}]},[],[{id:'contents',kind:'Contents item'}]),/type must match/);});
test('unavailable original projection withholds photo source proof',async()=>{await begin();await accept();const id=await photoEvidence();m.sqlite.prepare("UPDATE company_assets SET revision='2' WHERE id='damage'").run();const f=(await(await get(jobId)).json()).inbox.files.find(f=>f.evidenceId===id);assert.equal(f.available,false);assert.equal(f.sourceProof,null);assert.equal(photoLib.samePhotoSource(null,null),false);});
test('full photo record capacity prevents external examination before the provider call',async()=>{await begin();await accept();const id=await photoEvidence(),j=state();j.photoRuns=Array.from({length:100},(_,i)=>({id:crypto.randomUUID(),evidenceId:id,role:'water',method:'Manual',at:'2020-01-01T00:00:00Z',confirmed:null}));m.sqlite.prepare('UPDATE shared_jobs SET state=? WHERE id=?').run(JSON.stringify(j),jobId);const r=await photoPost({action:'examine',...inboxScope,evidenceId:id,consent:true});assert.equal(r.status,413);assert.equal(state().photoRuns.length,100);});

test('a refreshed job cannot let an older draft editor overwrite a newer correction or review',async()=>{const {d}=await createContentsDraft();const revision=d.history.length;const updated={...d.fields,label:'Corrected refrigerator lead'};assert.equal((await post({action:'draftEdit',...inboxScope,draftId:d.id,fields:updated,sourceChecked:true})).status,200);const before=state().evidenceDrafts[0];for(const body of [{action:'draftEdit',fields:d.fields,sourceProofs:[]},{action:'draftSubmit',note:'Old review'},{action:'draftReview',decision:'Reviewed for handoff',note:'Old decision'},{action:'draftDismiss',note:'Old dismissal'}]){const r=await post({...body,...inboxScope,draftId:d.id,draftRevision:revision,...(body.action==='draftDismiss'?{}:{sourceChecked:true})});assert.equal(r.status,409,await r.clone().text());}assert.deepEqual(state().evidenceDrafts[0],before);const v=(await(await get(jobId)).json()).inbox.evidenceDrafts[0];assert.equal(v.draftRevision,2);assert.equal(v.fields.label,updated.label);});
async function draftAdditionalOriginal(){asset('measurements','water','water-client');const r=await post({action:'contribute',...inboxScope,assetId:'measurements',category:'Room measurements',description:'Synthetic measured source',noSensitiveData:true});assert.equal(r.status,200,await r.clone().text());const e=state().evidence.at(-1);return {e,proof:{evidenceId:e.id,digest:e.digest,sourceCreated:e.sourceCreated,revision:e.revision}};}
test('selected additional original proof remains bound across a valid job refresh',async()=>{const {d}=await createContentsDraft(),{e,proof}=await draftAdditionalOriginal(),j=state();j.evidence=j.evidence.map(v=>v.id===e.id?{...v,revision:'2'}:v);m.sqlite.prepare('UPDATE shared_jobs SET state=?,version=version+1 WHERE id=?').run(JSON.stringify(j),jobId);m.sqlite.prepare("UPDATE company_assets SET revision='2' WHERE id='measurements'").run();const fields={...d.fields,supportingEvidenceIds:[e.id]};const r=await post({action:'draftEdit',...inboxScope,draftId:d.id,fields,sourceProofs:[proof],sourceChecked:true});assert.equal(r.status,409);assert.match((await r.json()).error,/supporting original changed/);assert.equal(state().evidenceDrafts[0].sources.length,1);assert.equal((await post({action:'draftEdit',...inboxScope,draftId:d.id,fields,sourceProofs:[{...proof,revision:'2'}],sourceChecked:true})).status,200);assert.equal(state().evidenceDrafts[0].sources.at(-1).revision,'2');});
test('additional original proof set must match the selected source IDs exactly',async()=>{const {d}=await createContentsDraft(),{e,proof}=await draftAdditionalOriginal(),fields={...d.fields,supportingEvidenceIds:[e.id]};for(const sourceProofs of [[],[proof,proof],[{...proof,evidenceId:'foreign'}]]){assert.equal((await post({action:'draftEdit',...inboxScope,draftId:d.id,fields,sourceProofs,sourceChecked:true})).status,400);}assert.equal(state().evidenceDrafts[0].history.length,1);assert.equal((await post({action:'draftEdit',...inboxScope,draftId:d.id,fields,sourceProofs:[proof],sourceChecked:true})).status,200);});
test('draft revision is independent of source-redacted history and missing revision fails closed',async()=>{const {d}=await createContentsDraft(),{e,proof}=await draftAdditionalOriginal();await post({action:'draftEdit',...inboxScope,draftId:d.id,fields:{...d.fields,supportingEvidenceIds:[e.id]},sourceProofs:[proof],sourceChecked:true});const saved=state().evidenceDrafts[0];await post({action:'draftEdit',...inboxScope,draftId:d.id,fields:{...saved.fields,label:'Updated source-backed lead'},sourceProofs:[proof],sourceChecked:true});m.setUser(home);assert.equal((await post({action:'withdrawEvidence',evidenceId:e.id,reason:'Synthetic supporting original withdrawn'})).status,200);m.setUser(arman);const v=(await(await get(jobId)).json()).inbox.evidenceDrafts[0];assert.equal(v.draftRevision,3);assert.equal(v.active,false);assert.ok(v.history.length<v.draftRevision);const r=await post({action:'draftDismiss',...inboxScope,draftId:d.id,draftRevision:undefined,note:'Missing version'});assert.equal(r.status,400);assert.equal(state().evidenceDrafts[0].status,'Draft');assert.equal((await post({action:'draftDismiss',...inboxScope,draftId:d.id,draftRevision:v.draftRevision,note:'Superseded supporting original'})).status,200);});

test('missing request revision binds a review to the exact workflow state after job refresh',async()=>{const {r}=await requestToHome();await homeownerResponse(r);m.setUser(arman);const opened=(await(await get(jobId)).json()).inbox.missingEvidence[0];assert.equal(opened.requestRevision,2);assert.equal((await post({action:'missingReviewStart',...inboxScope,requestId:r.id})).status,200);const before=state().missingEvidence[0];assert.equal((await post({action:'missingReview',...inboxScope,requestId:r.id,requestRevision:opened.requestRevision,decision:'Complete',note:'Older response review',sourceChecked:true})).status,409);assert.deepEqual(state().missingEvidence[0],before);assert.equal((await post({action:'missingCancel',...inboxScope,requestId:r.id,requestRevision:undefined,note:'Missing revision'})).status,400);});
test('responding requires the selected original version even after a valid homeowner job refresh',async()=>{const {r}=await requestToHome();m.setUser(home);const upload=await uploadInbox('', '%PDF-version-bound-response');assert.equal(upload.status,201);const id=(await upload.json()).evidenceId;await post({action:'share',evidenceId:id,companyIds:['water'],includeADPA:false,consent:true});const j=state(),e=j.evidence.find(e=>e.id===id),responseProof={digest:e.digest,sourceCreated:e.sourceCreated,revision:e.revision};e.revision='new-response';m.sqlite.prepare('UPDATE shared_jobs SET state=?,version=version+1 WHERE id=?').run(JSON.stringify(j),jobId);let result=await post({action:'missingRespond',requestId:r.id,responseEvidenceId:id,responseProof,note:'Opened earlier version',sourceChecked:true});assert.equal(result.status,409);assert.match((await result.json()).error,/selected response original changed/);assert.equal(state().missingEvidence[0].responses.length,0);assert.equal((await post({action:'missingRespond',requestId:r.id,responseEvidenceId:id,responseProof:{...responseProof,revision:'new-response'},note:'Examined current response',sourceChecked:true})).status,200);});
test('changed response bytes prevent requester review despite matching stored metadata',async()=>{const {r}=await requestToHome(),id=await homeownerResponse(r),e=state().evidence.find(e=>e.id===id);const changed=new TextEncoder().encode('%PDF-corrupted-response').buffer;m.storage.set(e.originalKey,{async arrayBuffer(){return changed;}});m.setUser(arman);const result=await post({action:'missingReviewStart',...inboxScope,requestId:r.id});assert.equal(result.status,409);assert.match((await result.json()).error,/Original bytes changed/);assert.equal(state().missingEvidence[0].status,'Uploaded');assert.equal(state().missingEvidence[0].reviews.length,0);});
test('requester can reopen a completed evidence request with history and new assignee action intact',async()=>{const {r}=await requestToHome();await homeownerResponse(r);m.setUser(arman);await post({action:'missingReviewStart',...inboxScope,requestId:r.id});await post({action:'missingReview',...inboxScope,requestId:r.id,decision:'Complete',note:'Initial source review',sourceChecked:true});const completed=state().missingEvidence[0];m.setUser(home);assert.equal((await post({action:'missingReopen',requestId:r.id,note:'Assignee cannot reopen requester decision',sourceChecked:true})).status,400);m.setUser(arman);assert.equal((await post({action:'missingReopen',...inboxScope,requestId:r.id,note:'Need clearer model-label photograph after review',sourceChecked:true})).status,200);const reopened=state().missingEvidence[0];assert.equal(reopened.status,'Requested');assert.deepEqual(reopened.responses,completed.responses);assert.deepEqual(reopened.reviews.slice(0,-1),completed.reviews);assert.equal(reopened.reviews.at(-1).action,'Reopened');m.setUser(home);const v=(await(await get(jobId)).json());assert.equal(v.inbox.missingEvidence[0].requestRevision,5);assert.ok(checklistLib.informationChecklist(v,'homeowner','2026-10-13')[0].mine);assert.equal((await post({action:'missingReopen',requestId:r.id,note:'Already reopened',sourceChecked:true})).status,400);});
test('completion requires an explicit outcome and reopening still honors response consent',async()=>{const {r}=await requestToHome(),id=await homeownerResponse(r);m.setUser(arman);await post({action:'missingReviewStart',...inboxScope,requestId:r.id});assert.equal((await post({action:'missingReview',...inboxScope,requestId:r.id,decision:'',note:'No choice yet',sourceChecked:true})).status,400);await post({action:'missingReview',...inboxScope,requestId:r.id,decision:'Complete',note:'Checked current response',sourceChecked:true});m.setUser(home);await post({action:'share',evidenceId:id,companyIds:[],includeADPA:false,consent:true});m.setUser(arman);const v=(await(await get(jobId)).json()).inbox.missingEvidence[0];assert.equal(v.requestRevision,4);assert.ok(v.reviews.length<3);assert.equal(v.responses.length,0);assert.equal((await post({action:'missingReopen',...inboxScope,requestId:r.id,note:'Cannot reopen without shared response',sourceChecked:true})).status,400);assert.equal(state().missingEvidence[0].status,'Complete');});

test('inspection saves stay bound to the versions of originals selected before a refreshed job',async()=>{await begin();await accept();const id=await contribute(),input=inspection(id),j=state(),e=j.evidence.find(e=>e.id===id),proof={evidenceId:id,digest:e.digest,sourceCreated:e.sourceCreated,revision:e.revision};e.revision='2';m.sqlite.prepare('UPDATE shared_jobs SET state=?,version=version+1 WHERE id=?').run(JSON.stringify(j),jobId);m.sqlite.prepare("UPDATE company_assets SET revision='2' WHERE id='damage'").run();let r=await post({...input,sourceProofs:[proof]});assert.equal(r.status,409);assert.equal(state().inspections,undefined);r=await post({...input,sourceProofs:[{...proof,revision:'2'}]});assert.equal(r.status,200,await r.clone().text());assert.equal(state().inspections[0].sources[0].revision,'2');const v=(await(await get(jobId)).json()).inspections[0];assert.equal(v.sources[0].sourceProof.revision,'2');});
test('inspection proof set must match every selected source and missing proof fails closed',async()=>{await begin();await accept();const id=await contribute(),input=inspection(id),e=state().evidence.find(e=>e.id===id),p={evidenceId:id,digest:e.digest,sourceCreated:e.sourceCreated,revision:e.revision};for(const sourceProofs of [undefined,[],[p,p],[{...p,evidenceId:'foreign'}]])assert.equal((await post({...input,sourceProofs})).status,400);assert.equal(state().inspections,undefined);});
test('inspection originals need actual available bytes matching saved digest and length',async()=>{await begin();await accept();const id=await contribute(),input=inspection(id);m.storage.delete('original/damage');let r=await post(input);assert.equal(r.status,409);assert.match((await r.json()).error,/unavailable/);const bytes=new TextEncoder().encode('%PDF-wrong-source').buffer;m.storage.set('original/damage',{async arrayBuffer(){return bytes;}});r=await post(input);assert.equal(r.status,409);assert.match((await r.json()).error,/bytes changed/);assert.equal(state().inspections,undefined);});
test('inspection corrections follow a single chain rather than branching an earlier observation',async()=>{await begin();await accept();const id=await contribute();assert.equal((await post(inspection(id,'original'))).status,200);const first=inspection(id,'correction-one');Object.assign(first.record,{width:'11',correctionOf:'original',correctionReason:'Correct recorded width'});assert.equal((await post(first)).status,200);const branch=inspection(id,'competing-correction');Object.assign(branch.record,{width:'13',correctionOf:'original',correctionReason:'Older form trying a second branch'});assert.equal((await post(branch)).status,409);assert.equal(state().inspections.length,2);branch.record.correctionOf='correction-one';assert.equal((await post(branch)).status,200);assert.deepEqual(state().inspections.map(r=>r.width),['10','11','13']);const v=(await(await get(jobId)).json()).inspections;assert.equal(v.find(r=>r.id==='original').corrected,true);assert.equal(v.find(r=>r.id==='correction-one').corrected,true);assert.equal(v.find(r=>r.id==='competing-correction').corrected,false);});
test('correcting an inspection pauses its older question handoff and preserves prior ADPA answers',async()=>{await begin();await accept();const id=await contribute();await post(inspection(id,'question-original'));await connect();m.setUser(home);await post({action:'share',evidenceId:id,companyIds:[],includeADPA:true,consent:true});m.setUser(arman);assert.equal((await post({action:'sendInspectionQuestion',...inboxScope,inspectionId:'question-original',noSensitiveData:true})).status,200);const task=state().tasks.find(t=>t.inspectionId==='question-original');m.setUser(owner);assert.equal((await post({action:'answerInspectionQuestion',taskId:task.id,answer:'Check the recorded cavity evidence before final scoping.'})).status,200);m.setUser(arman);const fix=inspection(id,'question-correction');Object.assign(fix.record,{correctionOf:'question-original',correctionReason:'Inspection facts corrected'});assert.equal((await post(fix)).status,200);const v=(await(await get(jobId)).json()).inspections;assert.equal(v.find(r=>r.id==='question-original').questionReady,false);assert.equal(v.find(r=>r.id==='question-original').questionTask.paused,true);assert.equal((await post({action:'resolveInspectionQuestion',...inboxScope,taskId:task.id,note:'Cannot use older answer after correction'})).status,409);m.setUser(owner);assert.equal((await post({action:'answerInspectionQuestion',taskId:task.id,answer:'Cannot answer superseded inspection'})).status,409);assert.equal(state().tasks.find(t=>t.id===task.id).answers.length,1);m.setUser(arman);assert.equal((await post({action:'sendInspectionQuestion',...inboxScope,inspectionId:'question-correction',noSensitiveData:true})).status,200);});
const inspectionClient=await import(new URL('inspection-review-client.mjs',base));
test('correction datetime helper retains the original observation instant and precision',()=>{const actual='2026-10-10T12:34:56.123Z',value=inspectionClient.inspectionLocalTime(actual);assert.equal(new Date(value).toISOString(),actual);assert.equal(inspectionClient.inspectionLocalTime('invalid'),'');});

test('company resolution must reference the latest ADPA answer after a refreshed job',async()=>{await questionSetup();await post(sendQuestion());const task=state().tasks.at(-1);m.setUser(owner);await post({action:'answerInspectionQuestion',taskId:task.id,answer:'First source-backed guidance'});m.setUser(arman);const opened=(await(await get(jobId)).json()).inspections[0].questionTask;assert.equal(opened.questionRevision,2);m.setUser(owner);await post({action:'answerInspectionQuestion',taskId:task.id,answer:'Additional guidance from the same current originals'});m.setUser(arman);let r=await post({action:'resolveInspectionQuestion',...inboxScope,taskId:task.id,questionRevision:opened.questionRevision,note:'Resolution drafted against the first answer'});assert.equal(r.status,409);assert.equal(state().tasks.at(-1).status,'Open');r=await post({action:'resolveInspectionQuestion',...inboxScope,taskId:task.id,note:'Examined both answers and current originals'});assert.equal(r.status,200);const saved=state().tasks.at(-1);assert.equal(saved.resolvedAnswerCount,2);assert.equal(saved.answers.length,2);assert.equal((await(await get(jobId)).json()).inspections[0].questionTask.questionRevision,4);});
test('ADPA answer drafts cannot append against an outdated question thread',async()=>{await questionSetup();await post(sendQuestion());const task=state().tasks.at(-1);m.setUser(owner);assert.equal((await post({action:'answerInspectionQuestion',taskId:task.id,questionRevision:1,answer:'First reviewed answer'})).status,200);assert.equal((await post({action:'answerInspectionQuestion',taskId:task.id,questionRevision:1,answer:'Older draft answer'})).status,409);assert.equal(state().tasks.at(-1).answers.length,1);assert.equal((await post({action:'answerInspectionQuestion',taskId:task.id,questionRevision:2,answer:'Supplement after reviewing current thread'})).status,200);assert.deepEqual(state().tasks.at(-1).answers.map(a=>a.body),['First reviewed answer','Supplement after reviewing current thread']);});
test('inspection answers and resolutions require a revision and deliberate original review',async()=>{await questionSetup();await post(sendQuestion());const task=state().tasks.at(-1);m.setUser(owner);for(const patch of [{questionRevision:undefined},{sourceChecked:false},{sourceChecked:undefined}])assert.equal((await post({action:'answerInspectionQuestion',taskId:task.id,answer:'Unchecked answer',...patch})).status,400);assert.equal(state().tasks.at(-1).answers.length,0);await post({action:'answerInspectionQuestion',taskId:task.id,answer:'Checked answer'});m.setUser(arman);assert.equal((await post({action:'resolveInspectionQuestion',...inboxScope,taskId:task.id,note:'Unchecked resolution',sourceChecked:false})).status,400);assert.equal(state().tasks.at(-1).status,'Open');});
test('missing or changed source bytes block question sending, answering and resolving',async()=>{await questionSetup();const original=m.storage.get('original/damage');m.storage.delete('original/damage');assert.equal((await post(sendQuestion())).status,409);assert.equal(state().tasks.length,0);m.storage.set('original/damage',original);assert.equal((await post(sendQuestion())).status,200);const task=state().tasks.at(-1);m.setUser(owner);m.storage.delete('original/damage');assert.equal((await post({action:'answerInspectionQuestion',taskId:task.id,answer:'Cannot answer absent originals'})).status,409);m.storage.set('original/damage',original);assert.equal((await post({action:'answerInspectionQuestion',taskId:task.id,answer:'Examined current original'})).status,200);const bytes=new TextEncoder().encode('%PDF-different-original').buffer;m.storage.set('original/damage',{async arrayBuffer(){return bytes;}});m.setUser(arman);const r=await post({action:'resolveInspectionQuestion',...inboxScope,taskId:task.id,note:'Cannot resolve against changed bytes'});assert.equal(r.status,409);assert.match((await r.json()).error,/bytes changed/);assert.equal(state().tasks.at(-1).status,'Open');});
test('question revision and resolution binding do not expose the thread to another company',async()=>{const e=await questionSetup();await post(sendQuestion());const task=state().tasks.at(-1);m.setUser(owner);await post({action:'answerInspectionQuestion',taskId:task.id,answer:'Private to requester and policyholder'});m.setUser(home);assert.equal((await post({action:'share',evidenceId:e,companyIds:['contents'],includeADPA:true,consent:true})).status,200);m.setUser(ana);const v=(await(await get(jobId)).json());assert.equal(v.inspections[0].questionTask,null);assert.ok(!JSON.stringify(v.inspections).includes('Private to requester'));assert.equal((await post({action:'resolveInspectionQuestion',companyId:'contents',companyVersion:1,taskId:task.id,note:'Another company cannot resolve'})).status,400);m.setUser(home);const h=(await(await get(jobId)).json()).inspections[0].questionTask;assert.equal(h.questionRevision,2);assert.equal(h.resolvedAnswerCount,null);});

test('transfer send requires the reviewed draft revision selected before refreshing',async()=>{const {d}=await readyTransfer(),old=d.history.length,j=state();j.evidenceDrafts[0].history.push({action:'Later source review',role:'water',at:'2026-10-13T12:00:00Z'});m.sqlite.prepare('UPDATE shared_jobs SET state=?,version=version+1 WHERE id=?').run(JSON.stringify(j),jobId);const r=await transferPost({action:'send',...inboxScope,draftId:d.id,draftRevision:old,destination:'Contents inventory',confirmed:true});assert.equal(r.status,409);assert.match((await r.json()).error,/draft changed/);assert.equal(JSON.parse(m.sqlite.prepare("SELECT state FROM claims WHERE id='claim'").get().state).evidenceTransfers,undefined);});
test('a reviewed draft already accepted stays one working item even after later history changes',async()=>{const {d}=await readyTransfer();await transferPost({action:'send',...inboxScope,draftId:d.id,destination:'Contents inventory',confirmed:true});const t=JSON.parse(m.sqlite.prepare("SELECT state FROM claims WHERE id='claim'").get().state).evidenceTransfers[0];m.setUser(owner);assert.equal((await transferPost(acceptance(t))).status,200);const j=state();j.evidenceDrafts[0].history.push({action:'Later review',role:'water',at:'2026-10-13T12:00:00Z'});m.sqlite.prepare('UPDATE shared_jobs SET state=?,version=version+1 WHERE id=?').run(JSON.stringify(j),jobId);m.setUser(arman);const response=await transferPost({action:'send',...inboxScope,draftId:d.id,destination:'Contents inventory',confirmed:true});assert.equal(response.status,200);assert.equal((await response.json()).alreadySent,true);const c=JSON.parse(m.sqlite.prepare("SELECT state FROM claims WHERE id='claim'").get().state);assert.equal(c.evidenceTransfers.length,1);assert.equal(c.contentsCare.items.length,1);});
test('scope transfer retains every supporting original and quantity locator without adding prices',()=>{const t={id:'transfer',jobId:'job',draftId:'draft',destination:'Reconstruction scope',originRole:'water',draft:{fields:{label:'Wall repair',description:'Observed wall damage',visibleIdentity:'Painted wall',quantity:'20',unit:'SF',quantityBasis:'Measured wall',basisEvidenceId:'quantity',basisLocator:'Page 2',areaId:'area',subjectId:'wall'},sources:[{evidenceId:'photo',locator:'Center'},{evidenceId:'quantity',locator:'Page 2'},{evidenceId:'detail',locator:'Left wall'}]}};const retained=[{id:'p',originalId:'photo',asset:{mime:'image/jpeg'}},{id:'q',originalId:'quantity',asset:{mime:'application/pdf'}},{id:'d',originalId:'detail',asset:{mime:'image/jpeg'}}],input={roomId:'',roomName:'Kitchen',operation:'Repair',workKey:'WALL-1',unit:'SF',locator:'Center',note:'Sources checked'};const r=transferLib.acceptTransfer({},t,input,retained,'2026-10-13T12:00:00Z','pa@example.test'),line=r.state.water.lines[0];assert.deepEqual(line.citations.map(c=>c.fileId),['p','q','d']);assert.equal(line.citations[1].page,2);assert.match(line.citations[1].quote,/Measured wall/);assert.equal(line.unitPrice,'');assert.equal(r.state.draftTransferSources[r.targetId].subjectId,'wall');assert.throws(()=>transferLib.acceptTransfer({water:{rooms:[{id:'room',name:'Kitchen'}]}},t,{...input,roomId:'room',roomName:'Wrong room'},retained,'2026-10-13T12:00:00Z','pa@example.test'),/current destination room/);});
test('different tags cannot duplicate an already accepted shared physical contents reference',()=>{const t={id:'second',jobId:'job',draftId:'new-draft',destination:'Contents inventory',draft:{fields:{quantity:'1',unit:'EA',quantityBasis:'Counted',basisEvidenceId:'photo',basisLocator:'Center',subjectId:'physical-item'},sources:[{evidenceId:'photo'}]}},s={evidenceTransfers:[{id:'first',status:'Accepted',jobId:'job',draftId:'old-draft',destination:'Contents inventory',draft:{fields:{subjectId:'physical-item'}}}]};assert.throws(()=>transferLib.acceptTransfer(s,t,{tag:'DIFFERENT-TAG'},[],'2026-10-13T12:00:00Z','pa@example.test'),/already accepted/);const key=transferLib.transferReviewKey(t,1,[]);assert.notEqual(key,transferLib.transferReviewKey(t,2,[]));assert.notEqual(key,transferLib.transferReviewKey({...t,active:false},1,[]));});

test('contents transfer preserves documented sets and boxes without multiplying physical counts',()=>{for(const [unit,expected] of [['SET','Set'],['Boxes','Box'],['EA','EA']]){const t={id:'transfer',jobId:'job',draftId:'draft',destination:'Contents inventory',originRole:'contents',draft:{fields:{label:'Documented contents group',description:'Damage recorded',visibleIdentity:'Source identity',quantity:'2',unit,quantityBasis:'Two source groups; pieces stay within each group',basisEvidenceId:'photo',basisLocator:'Center',subjectId:'physical-item'},sources:[{evidenceId:'photo',locator:'Center'}]}},r=transferLib.acceptTransfer({},t,{tag:'GROUP-1',roomName:'Kitchen',locator:'Center',note:'Group count reviewed'},[{id:'retained',originalId:'photo',asset:{mime:'image/jpeg'}}],'2026-10-13T12:00:00Z','pa@example.test');assert.equal(r.state.contentsCare.items[0].quantity,'2');assert.equal(r.state.contentsCare.items[0].unit,expected);assert.equal(r.state.contentsCare.items[0].disposition,'Needs review');}});
